package android.graphics;import java.awt.geom.*;public class Path{public enum Direction{CW}final Path2D.Float path=new Path2D.Float();public void reset(){path.reset();}public void moveTo(float x,float y){path.moveTo(x,y);}public void lineTo(float x,float y){path.lineTo(x,y);}public void close(){path.closePath();}public void addOval(RectF r,Direction d){path.append(new Ellipse2D.Float(r.left,r.top,r.right-r.left,r.bottom-r.top),false);}public void set(Path p){path.reset();path.append(p.path,false);}public void transform(Matrix m){path.transform(m.transform);}public void offset(float x,float y){path.transform(AffineTransform.getTranslateInstance(x,y));}public boolean isEmpty(){return path.getCurrentPoint()==null;}}
